// Generated by scripts/sync-document-markdown.mjs; edit the shared Rust-server source.
// Small, shared Markdown renderer for study documents and dashboard notes.
// Raw HTML is always text. Only HTTP(S), mailto and relative links become anchors.

// Escapes source and attribute values before any generated markup is inserted.
function escapeMarkdownHtml(value) {
  return String(value ?? '').replace(/[&<>"']/g, ch => ({'&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;'}[ch]));
}

// Renders inline tokens in one pass so markup generated for one token cannot be reparsed.
function markdownInline(source) {
  const pattern = /\{\{[^{}]*\}\}|`([^`\n]+)`|\[([^\]\n]+)\]\(([^\s)]+)\)|\*\*([^*\n]+)\*\*|__([^_\n]+)__|~~([^~\n]+)~~|\*([^*\n]+)\*|_([^_\n]+)_|https:\/\/[^\s<>]+/g;
  let html = '', cursor = 0;
  for (const match of source.matchAll(pattern)) {
    html += escapeMarkdownHtml(source.slice(cursor, match.index));
    if (match[0].startsWith('{{')) html += escapeMarkdownHtml(match[0]);
    else if (match[1] !== undefined) html += `<code>${escapeMarkdownHtml(match[1])}</code>`;
    else if (match[2] !== undefined || match[0].startsWith('https://')) {
      const label = match[2] ?? match[0];
      const url = match[3] ?? match[0];
      try {
        const parsed = new URL(url, globalThis.location?.href || 'https://example.invalid/');
        html += ['http:', 'https:', 'mailto:'].includes(parsed.protocol)
          ? `<a href="${escapeMarkdownHtml(parsed.href)}" rel="noopener noreferrer" target="_blank">${escapeMarkdownHtml(label)}</a>`
          : escapeMarkdownHtml(label);
      } catch { html += escapeMarkdownHtml(label); }
    } else {
      const tag = match[4] !== undefined || match[5] !== undefined ? 'strong' : match[6] !== undefined ? 'del' : 'em';
      html += `<${tag}>${escapeMarkdownHtml(match[4] ?? match[5] ?? match[6] ?? match[7] ?? match[8])}</${tag}>`;
    }
    cursor = match.index + match[0].length;
  }
  return html + escapeMarkdownHtml(source.slice(cursor));
}

// Supports headings, paragraphs, emphasis, links, lists/tasks, quotes, rules and fenced code.
// Line breaks in existing plain-text notices are retained; no saved text is rewritten.
export function safeMarkdown(source) {
  const lines = String(source ?? '').replace(/\r\n?/g, '\n').split('\n');
  const blocks = [];
  let paragraph = [], list = [], listTag = '', quote = [], code = null;
  // Flushes a paragraph before the next block-level element.
  const flushParagraph = () => {
    if (paragraph.length) blocks.push(`<p>${paragraph.map(markdownInline).join('<br>')}</p>`);
    paragraph = [];
  };
  // Flushes one flat list while preserving ordered versus unordered semantics.
  const flushList = () => {
    if (list.length) blocks.push(`<${listTag}>${list.join('')}</${listTag}>`);
    list = []; listTag = '';
  };
  // Flushes a quoted passage as escaped inline Markdown.
  const flushQuote = () => {
    if (quote.length) blocks.push(`<blockquote>${quote.map(markdownInline).join('<br>')}</blockquote>`);
    quote = [];
  };
  for (const line of lines) {
    if (code !== null) {
      if (/^\s*```\s*$/.test(line)) { blocks.push(`<pre><code>${escapeMarkdownHtml(code.join('\n'))}</code></pre>`); code = null; }
      else code.push(line);
      continue;
    }
    if (/^\s*```/.test(line)) { flushParagraph(); flushList(); flushQuote(); code = []; continue; }
    if (!line.trim()) { flushParagraph(); flushList(); flushQuote(); continue; }
    const heading = line.match(/^ {0,3}(#{1,6})\s+(.+?)\s*#*$/);
    if (heading) { flushParagraph(); flushList(); flushQuote(); blocks.push(`<h${heading[1].length}>${markdownInline(heading[2])}</h${heading[1].length}>`); continue; }
    if (/^\s*(?:---+|\*\*\*+|___+)\s*$/.test(line)) { flushParagraph(); flushList(); flushQuote(); blocks.push('<hr>'); continue; }
    const item = line.match(/^\s*(?:([-+*])|\d+[.)])\s+(.+)$/);
    if (item) {
      flushParagraph(); flushQuote();
      const tag = item[1] ? 'ul' : 'ol';
      if (listTag && listTag !== tag) flushList();
      listTag = tag;
      const task = item[2].match(/^\[([ xX])\]\s+(.*)$/);
      list.push(task ? `<li><input type="checkbox" disabled ${task[1].toLowerCase() === 'x' ? 'checked' : ''}> ${markdownInline(task[2])}</li>` : `<li>${markdownInline(item[2])}</li>`);
      continue;
    }
    flushList();
    const quoted = line.match(/^\s*>\s?(.*)$/);
    if (quoted) { flushParagraph(); quote.push(quoted[1]); continue; }
    flushQuote(); paragraph.push(line);
  }
  if (code !== null) blocks.push(`<pre><code>${escapeMarkdownHtml(code.join('\n'))}</code></pre>`);
  flushParagraph(); flushList(); flushQuote();
  return blocks.join('');
}

// Public pages mark escaped source blocks explicitly; JavaScript replaces only their presentation.
export function enhanceDocumentMarkdown(root = document) {
  for (const source of root.querySelectorAll('[data-study-markdown]')) {
    const rendered = document.createElement('div');
    rendered.className = 'document-markdown';
    rendered.style.overflowWrap = 'anywhere';
    rendered.innerHTML = safeMarkdown(source.textContent);
    source.replaceWith(rendered);
  }
}
